//! Stable-toolchain smoke run of the cargo-fuzz target bodies: seed inputs
//! plus proptest-generated bytes. The real fuzzing runs with `cargo fuzz` on
//! nightly (see `fuzz/README.md`).

#[path = "fuzz/bodies.rs"]
mod fuzz_bodies;

use proptest::prelude::*;
use proptest::test_runner::FileFailurePersistence;

const COUNTS_TSV: &[u8] = b"\0gene\ts1\ts2\ts3\ns1\t1\t2\t3\ng2\t0\t5\t9\n";
const DESIGN_TSV: &[u8] = b"\x01sample\tintercept\tconditionB\ns1\t1\t0\ns2\t1\t1\n";

#[test]
fn seeds_do_not_panic() {
    for seed in [
        COUNTS_TSV,
        DESIGN_TSV,
        b"\x02sample\tvalue\ns1\t1.5\ns2\tNaN\n",
        b"\x03sample\tcondition\ns1\tA\ns2\tB\n",
        b"\0gene\ts1\ng1\t-1\ng1\t99999999999999999999\n",
        b"\0",
        b"",
    ] {
        fuzz_bodies::tsv_readers(seed);
    }
    for formula in [
        "~ condition",
        "~ batch + condition:dose + offset(log(age))",
        "~ poly(age, 3) * condition",
        "~ (((((",
        "~ I(age^1e308)",
        "~ 0 + condition + condition:batch - 1",
        // Unknown calls once recursed until the stack overflowed.
        "~ q(age)",
        "~q()",
        "~ f() + condition",
        "",
    ] {
        fuzz_bodies::formula(formula.as_bytes());
    }
    let mut extreme = vec![255];
    extreme.extend(std::iter::repeat_n(u32::MAX.to_le_bytes(), 8).flatten());
    fuzz_bodies::fixed_dispersion_wald(&extreme);
    fuzz_bodies::fixed_dispersion_wald(&[0; 33]);
}

proptest! {
    #![proptest_config(ProptestConfig {
        cases: 256,
        failure_persistence: Some(Box::new(FileFailurePersistence::Direct(
            "tests/fuzz_smoke.proptest-regressions",
        ))),
        ..ProptestConfig::default()
    })]

    #[test]
    fn readers_survive_random_bytes(data in prop::collection::vec(any::<u8>(), 0..512)) {
        fuzz_bodies::tsv_readers(&data);
    }

    #[test]
    fn readers_survive_mutated_tsv(
        positions in prop::collection::vec((0usize..64, any::<u8>()), 1..8),
        design in any::<bool>(),
    ) {
        let mut data = if design { DESIGN_TSV.to_vec() } else { COUNTS_TSV.to_vec() };
        for (position, byte) in positions {
            let position = 1 + position % (data.len() - 1);
            data[position] = byte;
        }
        fuzz_bodies::tsv_readers(&data);
    }

    #[test]
    fn formulas_survive_random_text(
        text in "~ ?[a-z0-9_:+*()^,. \\-/|]{0,40}",
    ) {
        fuzz_bodies::formula(text.as_bytes());
    }

    #[test]
    fn formula_wire_survives_random_bytes(data in prop::collection::vec(any::<u8>(), 0..512)) {
        fuzz_bodies::formula_wire(&data);
    }

    #[test]
    fn seed_and_cli_parsers_survive_random_bytes(data in prop::collection::vec(any::<u8>(), 0..2600)) {
        fuzz_bodies::r_seed(&data);
        fuzz_bodies::cli_args(&data);
    }

    #[test]
    fn fits_survive_random_counts(data in prop::collection::vec(any::<u8>(), 0..300)) {
        fuzz_bodies::fixed_dispersion_wald(&data);
    }
}
